package com.hippocampus.materials.application;
import java.util.Objects; import com.hippocampus.materials.domain.ClaimedProcessingJob; import com.hippocampus.materials.domain.ProcessingJobType;
public final class ChunkMaterialStageHandler implements ProcessingStageHandler {private final ChunkMaterialText chunking;public ChunkMaterialStageHandler(ChunkMaterialText c){chunking=Objects.requireNonNull(c);}@Override public ProcessingJobType jobType(){return ProcessingJobType.CHUNK;}@Override public void handle(ClaimedProcessingJob job){if(job.materialVersionId()==null)throw new IllegalArgumentException("CHUNK requires a material version");chunking.execute(job.materialVersionId());}}
